create extension if not exists pgcrypto;
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()) $$;
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,sort_order int not null default 0,active boolean not null default true);
create table if not exists public.dishes(id uuid primary key default gen_random_uuid(),name text not null,category_id uuid references public.categories(id),category_name text,description text not null default '',ingredients text[] not null default '{}',price_clp integer check(price_clp is null or price_clp>=0),image text not null default '',extras jsonb not null default '[]',available boolean not null default true,featured boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.settings(id boolean primary key default true check(id),whatsapp_number text,instagram_url text,tiktok_url text,address text default 'Labranza, Chile');
insert into public.settings(id) values(true) on conflict do nothing;
create table if not exists public.promotions(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',kind text not null check(kind in('weekly','seasonal')),starts_at date,ends_at date,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number bigint generated by default as identity unique,customer_name text not null,customer_phone text not null,customer_rut text not null,mode text not null check(mode in('delivery','pickup','table')),address text,table_number text,notes text not null default '',items jsonb not null,total_clp integer not null,status text not null default 'nuevo',created_at timestamptz not null default now());
alter table public.admins enable row level security;alter table public.categories enable row level security;alter table public.dishes enable row level security;alter table public.settings enable row level security;alter table public.orders enable row level security;alter table public.promotions enable row level security;
create policy "admins read own membership" on public.admins for select using(user_id=auth.uid());
create policy "public reads categories" on public.categories for select using(active or public.is_admin());create policy "admins manage categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads available dishes" on public.dishes for select using(available or public.is_admin());create policy "admins manage dishes" on public.dishes for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads settings" on public.settings for select using(true);create policy "admins update settings" on public.settings for update using(public.is_admin()) with check(public.is_admin());
create policy "public reads active promotions" on public.promotions for select using(active and (starts_at is null or starts_at<=current_date) and (ends_at is null or ends_at>=current_date));create policy "admins manage promotions" on public.promotions for all using(public.is_admin()) with check(public.is_admin());
create policy "admins manage orders" on public.orders for all using(public.is_admin()) with check(public.is_admin());
create or replace function public.create_order(p_customer jsonb,p_items jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare line jsonb; dish_row public.dishes; qty int; line_total int; total int:=0; items_snapshot jsonb:='[]'::jsonb; saved public.orders; mode_value text; begin
 if jsonb_array_length(p_items)=0 then raise exception 'El pedido está vacío'; end if;
 mode_value:=p_customer->>'mode'; if mode_value not in('delivery','pickup','table') then raise exception 'Modalidad inválida'; end if;
 if length(trim(coalesce(p_customer->>'name','')))<2 or length(trim(coalesce(p_customer->>'phone','')))<7 or length(trim(coalesce(p_customer->>'rut','')))<8 then raise exception 'Faltan datos válidos del cliente'; end if;
 if mode_value='delivery' and length(trim(coalesce(p_customer->>'address','')))<5 then raise exception 'Falta la dirección'; end if;
 for line in select * from jsonb_array_elements(p_items) loop select * into dish_row from public.dishes where id=(line->>'dish_id')::uuid and available=true; if not found or dish_row.price_clp is null then raise exception 'Plato no disponible'; end if; qty:=greatest(1,least(20,(line->>'quantity')::int)); line_total:=dish_row.price_clp*qty; if jsonb_typeof(line->'extras')='array' then declare extra_name text; extra_row jsonb; extra_price int; begin for extra_name in select jsonb_array_elements_text(line->'extras') loop select value into extra_row from jsonb_array_elements(dish_row.extras) where value->>'name'=extra_name; if extra_row is null then raise exception 'Extra inválido'; end if; extra_price:=greatest(0,coalesce((extra_row->>'price_clp')::int,0)); line_total:=line_total+extra_price*qty; end loop; end; end if; total:=total+line_total; items_snapshot:=items_snapshot||jsonb_build_array(jsonb_build_object('dish_id',dish_row.id,'name',dish_row.name,'quantity',qty,'unit_price_clp',dish_row.price_clp,'extras',coalesce(line->'extras','[]'::jsonb),'line_total_clp',line_total)); end loop;
 insert into public.orders(customer_name,customer_phone,customer_rut,mode,address,table_number,notes,items,total_clp) values(trim(p_customer->>'name'),trim(p_customer->>'phone'),trim(p_customer->>'rut'),mode_value,nullif(trim(p_customer->>'address'),''),nullif(trim(p_customer->>'table_number'),''),coalesce(p_customer->>'notes',''),items_snapshot,total) returning * into saved;
 return jsonb_build_object('id',saved.id,'number',saved.order_number,'total_clp',saved.total_clp); end $$;
grant execute on function public.create_order(jsonb,jsonb) to anon,authenticated;
insert into public.categories(name,sort_order) values('Hamburguesas',1),('Pizzas',2),('Completos',3),('As',4),('Bowls',5),('Menú saludable',6),('Sandwiches',7),('Bebidas',8),('Combos',9) on conflict(name) do nothing;
